item.content:encoded:
.single-articles .entry-content {
    margin: 10px 10px;
Left/Right: 10px ; /* Top/Bottom: 20px, (adjust values as needed) */
}

.wp-block-cover {
    max-height: 200px !important;
}
/* page-template*/
.page-template-default #primary.content-area {
    margin: 40px 20px; 
    max-width: 978px !important; 
	  width: 100% !important;
    box-sizing: border-box;

}/*Site Header */
.site-header {
width: 100%;
position: fixed !important;
top: 0;
left: 0;
z-index: 9999;
height: 30px;
}

/* Primary Content Area */
#primary.content-area {
margin: 0 auto; 
padding-left: 0;
padding-top: 20px;
margin-top: 20px;
width: 100%;
max-width: 768px;
box-sizing: border-box;

}

.site-main {
max-width: 978px; 
margin: 0 auto;
width: 100%;
box-sizing: border-box;
}

/* Main Header 
.main-header-bar {
display: block !important;
}*/

#primary.site-content {
padding-top: 0px;
}

.site-header .site-title {
font-size: 2em;
height: 30px;
color: #000000 !important;
}

/* RHS menu */
.site-header .main-navigation,
.site-header .menu-item {
font-size: 1.2em;
line-height: 40px;
}

.wp-block-details > summary {
    font-size: 1.4em;
    font-weight: bold;
}

.entry-title {
font-size: 1.5em !important;
font-weight: 700 !important;
text-decoration: underline !important;
margin: 0 0 10px 0 !important;
padding: 0;
line-height: 1.2;
}

/* Remove additional margins/padding from parent elements */
.ast-article-post {
margin-top: 150px;
padding-top: 0;
}

main.site-content {
padding-top: 0px;
}

/* Post Header */
.ast-post-format--single .ast-article-post .entry-header {
text-align: center;
padding: 2px 0;
margin: 0;
}

.entry-series-name {
font-size: 1.4em;
font-weight: 600;
margin: 0 0 2px 0;
padding: 0;
line-height: 1.2;
}

/* Base class for common heading styles */
.header-text {
font-family: Verdana, sans-serif;
}

/* Specific heading styles with graduated backgrounds */
/* Tribulation */
h2 {
font-family: Helvetica, sans-serif;
background: linear-gradient(to top, #ff0000, #FFF056);
font-size: 1.4em;
font-weight: 600;
font-style: italic;
color: #ffffff !important;
margin: 0 0 10px 0;
padding: 5px 10px;
}

/* 1000 yrs */
h3 {
font-family: Helvetica, sans-serif;
background: linear-gradient(to top, #006633, #FFF056);
font-size: 1.3em;
font-weight: 600;
font-style: italic;
color: #ffffff !important;
margin: 0 0 10px 0;
padding: 5px 10px;
}

/* Eternity */
h4 {
font-family: Helvetica, sans-serif;
background: linear-gradient(to left, #ffffff, #ffff00);
font-size: 1.2em;
font-weight: 600;
font-style: italic;
margin: 0 20px 10px 0;
padding: 5px 10px;
}

/* Ensure normal text and list items have the same line-height */
body {
font-family: Helvetica, sans-serif;
line-height: 1.4;
font-size: 1.0em;
font-weight: 400;
margin: 0 0 0 0;
padding: 0 0 0 0;
}

/* Target the ordered list and list items */
ol {
margin-left: 40px;
padding: 0 0 0 0;
}

/* Adjust spacing between list items */
ol li {
line-height: 1.4;
margin-top: 5px;
padding-left: 0;
}

/* Ensure paragraphs have consistent spacing */
p {
line-height: 1.4;
margin: 0 0 10px 0;
padding: 0 0 0 0;
}

/***
****************************
Article Menu
****************************
*/

.article-menu-page {
width: 100%; /* Full width to allow child centering */
min-height: calc(100vh - 110px); /* Adjust for header (30px) and footer (80px) */
margin: 0;
padding: 0;
display: flex;
justify-content: center;
align-items: flex-start;
}

.three-level-accordion-page {
padding: 20px;
max-width: 700px; 
width:100%;
margin: 0 auto;
margin-top: 40px; 
background-color: #f5f5f5;
box-sizing: border-box;
}

.accordion-container {
margin-top: 20px;
}

.accordion-level-1 > summary {
font-size: 1.4em;
font-weight: bold;
padding: 10px;
cursor: pointer;
background-color: #f5f5f5;
border-bottom: 1px solid #ddd;
}

.accordion-level-2 {
margin-left: 20px;
}

.accordion-level-2 > summary {
font-size: 1.3em;
font-weight: 600;
padding: 8px;
cursor: pointer;
background-color: #f9f9f9;
border-bottom: 1px solid #ddd;
}

.series-url {
margin: 5px 0 5px 20px;
font-size: 1em;
}

.series-url a {
color: #006633;
text-decoration: underline;
}

.accordion-level-3 {
margin-left: 40px;
}

.accordion-level-3 > summary {
font-size: 1.2em;
font-weight: 500;
padding: 6px;
cursor: pointer;
background-color: #fdfdfd;
border-bottom: 1px solid #ddd;
}

.accordion-level-3 > summary a {
color: #006633;
text-decoration: underline;
}

.accordion-level-3 p {
margin: 5px 0;
padding: 5px 10px;
font-size: 1em;
}

.article-series-side-menu {
position: fixed;
top: 104px; /* Adjusted for admin bar (32px) + site header (72px) */
left: 0;
margin-left: 20px;
width: 205px;
background-color: #f5f5f5;
z-index: 999;
padding: 10px;
box-shadow: 2px 0 5px rgba(0, 0, 0, 0.1);
}

.series-menu-header {
padding: 10px;
border-bottom: 1px solid #ddd;
}

.series-menu-title a {
font-size: 1.2em;
font-weight: bold;
color: #333;
text-decoration: none;
}

.series-menu-title a:hover {
text-decoration: underline;
}

.series-menu-list li {
padding: 2px 10px;
border-bottom: 1px solid #ddd;
}


/* Post Menu Styling 
--------------------*/
.menu-title {
    font-family: Helvetica, sans-serif;
    font-size: 1.2em;
    line-height: 1.4;
    margin: 0 0 10px 0;
    padding: 0;
    font-weight: bold;
}

.post-menu {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    justify-content: flex-start;
    flex-wrap: wrap;
    background-color: #f5f5f5;
    border-bottom: 1px solid #ddd;
}

.post-menu .menu-item {
    position: relative;
    margin: 0;
}

.post-menu .menu-link {
    display: block;
    padding: 10px 20px;
    font-size: 1.2em;
    font-weight: 500;
    color: #006633;
    text-decoration: underline;
    position: flex-start;
}

.post-menu .menu-link::before {
    content: "▶";
    font-size: 0.8em;
    margin-right: 5px;
    display: inline-block;
}

.post-menu .menu-link:hover {
    color: #00331A;
    text-decoration: none;
}

.post-menu .menu-link:focus {
    outline: 2px solid #006633;
    outline-offset: 2px;
}

/* YouTube
***************************************************/
.video-placeholder {
    position: relative;
    cursor: pointer;
}
.play-button {
    position: relative;
    display: inline-block;
}
.play-icon {
    position: absolute;
    top: 70%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 60px;
    height: 60px;
    background: rgba(0, 0, 0, 0.6);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}
.play-icon::before {
    content: '';
    display: block;
    width: 0;
    height: 0;
    border-left: 20px solid white;
    border-top: 12px solid transparent;
    border-bottom: 12px solid transparent;
}

1 Then I saw an angel coming down from heaven, <br>having the key to the bottomless pit and a great chain in his hand.

2 He laid hold of the <strong>dragon</strong>, that <strong>serpent</strong> of old, <br>who is the <strong>Devil</strong> and <strong>Satan</strong>, and bound him for a <strong>thousand years</strong>;

3 and he cast him into the bottomless pit, and shut him up, and set a seal on him, so that he should <strong>deceive the nations</strong> no more till the <strong>thousand years</strong> were finished. But after these things he must be released for a little while.

10 And<strong> I will pour on the house of David</strong> and on the inhabitants of Jerusalem the<strong> Spirit of grace</strong> and supplication;
then they will <strong>look on Me whom they pierced</strong>.
Yes, they will mourn for Him as one mourns for his only son, <br>and grieve for Him as one grieves for a firstborn.

6 Indeed He says, It is too small a thing that You should be My Servant to <strong>raise up the tribes of Jacob</strong>, and to restore the <strong>preserved ones of Israel</strong>;
<span style="color: #ff0000;"><strong>I will also give You as a light to the Gentiles</strong></span>,
That You should be My salvation to the ends of the earth.

3 Many people shall come and say, <br>Come, and <span style="color: #000000;">let us go up to the mountain of Yahweh,</span> <br>To the house of the God of Jacob;
<span style="color: #ff0000;"><strong>He will teach us His ways, and we shall walk in His paths</strong></span>.
For out of <strong>Zion</strong> shall go forth the <strong>law</strong>, <br>and the word of <strong>Yahweh</strong> from <strong>Jerusalem</strong>.

7 <strong>Eternal life</strong> to those who by patient continuance in doing good,<br>seek for <strong>glory</strong>, <strong>honor</strong>, and <strong>immortality</strong>;
8 but to those who are self-seeking and do not obey the truth, <br>but obey <strong>unrighteousness</strong> — <strong>indignation and wrath,
</strong>
9 <strong>tribulation and anguish,</strong> on every soul of man who <strong>does evil</strong>,<br>of the <strong>Jew first</strong> and <strong>also</strong> of the <strong>Greek</strong>;
10 but <strong>glory, honor, and peace</strong> to everyone who works what is good,<br>to the <strong>Jew first</strong> and <strong>also</strong> to the <strong>Greek</strong>.
11 For there is <strong>no partiality with God</strong>.

Col 1:9-14
9 For this reason we also, since the day we heard it, do not cease to pray for you, <br>and to ask that you may be filled with the <strong>knowledge of His will</strong> in all <strong>wisdom</strong> and <strong>spiritual understanding</strong>;
10 that you may <strong>walk worthy</strong> of the Lord, fully pleasing Him, <br>being <strong>fruitful</strong> in every good work and increasing in the <strong>knowledge of God</strong>;
11 strengthened with all might, according to <strong>His glorious power</strong>, <br>for all patience and <strong>longsuffering with joy</strong>;
12 <strong>giving thanks to the Father</strong> who has qualified us to be <strong>partakers of the inheritance</strong> of the saints in the light.
13 He has delivered us from the power of darkness and conveyed us into <strong>the kingdom of the Son of His love</strong>,
14 in whom we have <strong>redemption</strong> through His <strong>blood</strong>, the forgiveness of sins.
